window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fd74f4df3a3d476a"]={"versions": [{"id": "FIG-fd74f4df3a3d476a", "releases": ["R3.2.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein Speicher- und Puffer-Layout-Diagramm (Data Serialization & Layout Scheme) der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library). Es illustriert die Berechnung der Prüfsumme (CRC) für das E2E-Profil 1 in der Variante 1C (E2E Profile 1 variant 1C CRC calculation example). Der architektonische Kontext liegt im Schutz sicherheitskritischer Datenübertragungen (bis ASIL D) auf der Kommunikationsschicht gegen Übertragungs- und Speicherfehler (Informationsintegrität, Adressierungsfehler, Verfälschung).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist ein Byte-Array bzw. Datenpuffer bestehend aus mehreren Feldern sowie externen Eingangsdaten:</p>\n<ul class=\"fig-list\">\n<li><strong>Low byte of DataID</strong>: Externes Feld (1 Byte), das das niederwertige Byte des systemspezifischen Datenbezeichners (DataID) repräsentiert und in die Prüfsummenberechnung einfließt.</li>\n<li><strong>CRC</strong>: 1-Byte-Feld an Byte-Position 0 des Puffers, das die berechnete 8-Bit-Prüfsumme (CRC8) aufnimmt.</li>\n<li>*<em>\\</em>)**: Halb-Byte- bzw. Nibble-Feld im zweiten Byte, gekennzeichnet mit einem Sternchen (reserviert / ungenutzt oder applikationsspezifischer Teil).</li>\n<li><strong>Counter</strong>: 4-Bit-Sequenzzähler (Alive Counter) im selben Byte neben dem mit <code>*)</code> markierten Nibble zur Erkennung von Wiederholungs- und Verlustfehlern.</li>\n<li><strong>Sig1</strong>: Aufgeteilte Nutzdaten/Signalfelder im Puffer (teilweise als einzelnes Byte, teils über mehrere Bytes bzw. Füllbereiche gestreckt).</li>\n<li><strong>0xFF</strong>: Festes Füllbyte (Padding/Dummy-Wert <code>0x11111111_2</code> bzw. <code>255</code>), das an einer definierten Position innerhalb der Datenstruktur liegt.</li>\n<li><strong>Unbeschriftete Felder / Datenblöcke</strong>: Zusätzliche Daten- oder Signalbytes innerhalb des Gesamtlayouts.</li>\n<li><strong>Klammer & Pfeil (Berechnungspfad)</strong>: Eine geschweifte Klammer fasst den gesamten Datenbereich ab Byte 1 (nach dem CRC-Feld) bis zum Pufferende zusammen und führt gemeinsam mit dem <code>Low byte of DataID</code> über einen Pfeil direkt in das <code>CRC</code>-Feld.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Berechnungsablauf für Variante 1C vollzieht sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li>Das <code>Low byte of DataID</code> wird als Startwert/Initialisierung oder erstes Byte in den CRC8-Berechnungsalgorithmus eingespeist.</li>\n<li>Nacheinander werden alle Nutzdatenbytes des Puffers ab Byte-Index 1 (beginnend mit dem Nibble <code>*)</code> und dem <code>Counter</code>, gefolgt von <code>Sig1</code>, weiteren Datenbytes, dem Füllbyte <code>0xFF</code> sowie den abschließenden Signalbytes <code>Sig1</code>) in die CRC-Berechnung einbezogen.</li>\n<li>Das CRC-Feld selbst (Byte 0) wird bei der Berechnung ausgespart bzw. übersprungen.</li>\n<li>Das finale Ergebnis der Prüfsummenberechnung wird in das Ziel-Byte <code>CRC</code> an Offset 0 geschrieben (bzw. auf Empfängerseite mit dem dort empfangenen Wert verglichen).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Darstellung definiert normativ die Reihenfolge und den Umfang der Datenabdeckung für E2E Profile 1 Variante 1C:</p>\n<ul class=\"fig-list\">\n<li>Das CRC-Byte an Position 0 darf sich nicht selbst schützen und wird aus der Prüfsummenbildung ausgeschlossen.</li>\n<li>Das niederwertige Byte der DataID (<code>Low byte of DataID</code>) muss zwingend in die CRC-Berechnung einfließen, wird jedoch nicht explizit im Puffer über den Bus mitübertragen (implizite Adressprüfung / Schutz gegen Fehlrouting).</li>\n<li>Daten- und Signalpositionen inklusive Padding (<code>0xFF</code>), Zähler (<code>Counter</code>) und Teilsignale müssen bezüglich Byte- und Bit-Offset exakt nach den Vorgaben der Profilkonfiguration serialisiert werden, bevor die E2E-Schutzfunktion <code>E2E_P01Protect</code> ausgeführt bzw. <code>E2E_P01Check</code> evaluiert wird.</li>\n</ul>"}, {"id": "FIG-9e4713ec2e267662", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein Speicher- und Puffer-Layout-Diagramm (Data Serialization & Layout Scheme) der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library). Es illustriert die Berechnung der Prüfsumme (CRC) für das E2E-Profil 1 in der Variante 1C (E2E Profile 1 variant 1C CRC calculation example). Der architektonische Kontext liegt im Schutz sicherheitskritischer Datenübertragungen (bis ASIL D) auf der Kommunikationsschicht gegen Übertragungs- und Speicherfehler (Informationsintegrität, Adressierungsfehler, Verfälschung).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist ein Byte-Array bzw. Datenpuffer bestehend aus mehreren Feldern sowie externen Eingangsdaten:</p>\n<ul class=\"fig-list\">\n<li><strong>Low byte of DataID</strong>: Externes Feld (1 Byte), das das niederwertige Byte des systemspezifischen Datenbezeichners (DataID) repräsentiert und in die Prüfsummenberechnung einfließt.</li>\n<li><strong>CRC</strong>: 1-Byte-Feld an Byte-Position 0 des Puffers, das die berechnete 8-Bit-Prüfsumme (CRC8) aufnimmt.</li>\n<li>*<em>\\</em>)**: Halb-Byte- bzw. Nibble-Feld im zweiten Byte, gekennzeichnet mit einem Sternchen (reserviert / ungenutzt oder applikationsspezifischer Teil).</li>\n<li><strong>Counter</strong>: 4-Bit-Sequenzzähler (Alive Counter) im selben Byte neben dem mit <code>*)</code> markierten Nibble zur Erkennung von Wiederholungs- und Verlustfehlern.</li>\n<li><strong>Sig1</strong>: Aufgeteilte Nutzdaten/Signalfelder im Puffer (teilweise als einzelnes Byte, teils über mehrere Bytes bzw. Füllbereiche gestreckt).</li>\n<li><strong>0xFF</strong>: Festes Füllbyte (Padding/Dummy-Wert <code>0x11111111_2</code> bzw. <code>255</code>), das an einer definierten Position innerhalb der Datenstruktur liegt.</li>\n<li><strong>Unbeschriftete Felder / Datenblöcke</strong>: Zusätzliche Daten- oder Signalbytes innerhalb des Gesamtlayouts.</li>\n<li><strong>Klammer & Pfeil (Berechnungspfad)</strong>: Eine geschweifte Klammer fasst den gesamten Datenbereich ab Byte 1 (nach dem CRC-Feld) bis zum Pufferende zusammen und führt gemeinsam mit dem <code>Low byte of DataID</code> über einen Pfeil direkt in das <code>CRC</code>-Feld.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Berechnungsablauf für Variante 1C vollzieht sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li>Das <code>Low byte of DataID</code> wird als Startwert/Initialisierung oder erstes Byte in den CRC8-Berechnungsalgorithmus eingespeist.</li>\n<li>Nacheinander werden alle Nutzdatenbytes des Puffers ab Byte-Index 1 (beginnend mit dem Nibble <code>*)</code> und dem <code>Counter</code>, gefolgt von <code>Sig1</code>, weiteren Datenbytes, dem Füllbyte <code>0xFF</code> sowie den abschließenden Signalbytes <code>Sig1</code>) in die CRC-Berechnung einbezogen.</li>\n<li>Das CRC-Feld selbst (Byte 0) wird bei der Berechnung ausgespart bzw. übersprungen.</li>\n<li>Das finale Ergebnis der Prüfsummenberechnung wird in das Ziel-Byte <code>CRC</code> an Offset 0 geschrieben (bzw. auf Empfängerseite mit dem dort empfangenen Wert verglichen).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Darstellung definiert normativ die Reihenfolge und den Umfang der Datenabdeckung für E2E Profile 1 Variante 1C:</p>\n<ul class=\"fig-list\">\n<li>Das CRC-Byte an Position 0 darf sich nicht selbst schützen und wird aus der Prüfsummenbildung ausgeschlossen.</li>\n<li>Das niederwertige Byte der DataID (<code>Low byte of DataID</code>) muss zwingend in die CRC-Berechnung einfließen, wird jedoch nicht explizit im Puffer über den Bus mitübertragen (implizite Adressprüfung / Schutz gegen Fehlrouting).</li>\n<li>Daten- und Signalpositionen inklusive Padding (<code>0xFF</code>), Zähler (<code>Counter</code>) und Teilsignale müssen bezüglich Byte- und Bit-Offset exakt nach den Vorgaben der Profilkonfiguration serialisiert werden, bevor die E2E-Schutzfunktion <code>E2E_P01Protect</code> ausgeführt bzw. <code>E2E_P01Check</code> evaluiert wird.</li>\n</ul>"}, {"id": "FIG-25b9479fac583c8b", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein Speicher- und Puffer-Layout-Diagramm (Data Serialization & Layout Scheme) der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library). Es illustriert die Berechnung der Prüfsumme (CRC) für das E2E-Profil 1 in der Variante 1C (E2E Profile 1 variant 1C CRC calculation example). Der architektonische Kontext liegt im Schutz sicherheitskritischer Datenübertragungen (bis ASIL D) auf der Kommunikationsschicht gegen Übertragungs- und Speicherfehler (Informationsintegrität, Adressierungsfehler, Verfälschung).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist ein Byte-Array bzw. Datenpuffer bestehend aus mehreren Feldern sowie externen Eingangsdaten:</p>\n<ul class=\"fig-list\">\n<li><strong>Low byte of DataID</strong>: Externes Feld (1 Byte), das das niederwertige Byte des systemspezifischen Datenbezeichners (DataID) repräsentiert und in die Prüfsummenberechnung einfließt.</li>\n<li><strong>CRC</strong>: 1-Byte-Feld an Byte-Position 0 des Puffers, das die berechnete 8-Bit-Prüfsumme (CRC8) aufnimmt.</li>\n<li>*<em>\\</em>)**: Halb-Byte- bzw. Nibble-Feld im zweiten Byte, gekennzeichnet mit einem Sternchen (reserviert / ungenutzt oder applikationsspezifischer Teil).</li>\n<li><strong>Counter</strong>: 4-Bit-Sequenzzähler (Alive Counter) im selben Byte neben dem mit <code>*)</code> markierten Nibble zur Erkennung von Wiederholungs- und Verlustfehlern.</li>\n<li><strong>Sig1</strong>: Aufgeteilte Nutzdaten/Signalfelder im Puffer (teilweise als einzelnes Byte, teils über mehrere Bytes bzw. Füllbereiche gestreckt).</li>\n<li><strong>0xFF</strong>: Festes Füllbyte (Padding/Dummy-Wert <code>0x11111111_2</code> bzw. <code>255</code>), das an einer definierten Position innerhalb der Datenstruktur liegt.</li>\n<li><strong>Unbeschriftete Felder / Datenblöcke</strong>: Zusätzliche Daten- oder Signalbytes innerhalb des Gesamtlayouts.</li>\n<li><strong>Klammer & Pfeil (Berechnungspfad)</strong>: Eine geschweifte Klammer fasst den gesamten Datenbereich ab Byte 1 (nach dem CRC-Feld) bis zum Pufferende zusammen und führt gemeinsam mit dem <code>Low byte of DataID</code> über einen Pfeil direkt in das <code>CRC</code>-Feld.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Berechnungsablauf für Variante 1C vollzieht sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li>Das <code>Low byte of DataID</code> wird als Startwert/Initialisierung oder erstes Byte in den CRC8-Berechnungsalgorithmus eingespeist.</li>\n<li>Nacheinander werden alle Nutzdatenbytes des Puffers ab Byte-Index 1 (beginnend mit dem Nibble <code>*)</code> und dem <code>Counter</code>, gefolgt von <code>Sig1</code>, weiteren Datenbytes, dem Füllbyte <code>0xFF</code> sowie den abschließenden Signalbytes <code>Sig1</code>) in die CRC-Berechnung einbezogen.</li>\n<li>Das CRC-Feld selbst (Byte 0) wird bei der Berechnung ausgespart bzw. übersprungen.</li>\n<li>Das finale Ergebnis der Prüfsummenberechnung wird in das Ziel-Byte <code>CRC</code> an Offset 0 geschrieben (bzw. auf Empfängerseite mit dem dort empfangenen Wert verglichen).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Darstellung definiert normativ die Reihenfolge und den Umfang der Datenabdeckung für E2E Profile 1 Variante 1C:</p>\n<ul class=\"fig-list\">\n<li>Das CRC-Byte an Position 0 darf sich nicht selbst schützen und wird aus der Prüfsummenbildung ausgeschlossen.</li>\n<li>Das niederwertige Byte der DataID (<code>Low byte of DataID</code>) muss zwingend in die CRC-Berechnung einfließen, wird jedoch nicht explizit im Puffer über den Bus mitübertragen (implizite Adressprüfung / Schutz gegen Fehlrouting).</li>\n<li>Daten- und Signalpositionen inklusive Padding (<code>0xFF</code>), Zähler (<code>Counter</code>) und Teilsignale müssen bezüglich Byte- und Bit-Offset exakt nach den Vorgaben der Profilkonfiguration serialisiert werden, bevor die E2E-Schutzfunktion <code>E2E_P01Protect</code> ausgeführt bzw. <code>E2E_P01Check</code> evaluiert wird.</li>\n</ul>"}], "trans": [{"from": "FIG-fd74f4df3a3d476a", "to": "FIG-9e4713ec2e267662", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9e4713ec2e267662", "to": "FIG-25b9479fac583c8b", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
